//! BIDIR-19 · a method with an input half (`mdInput`; plexus-wire spec/10)
//! in the generated TypeScript and Rust clients.
//!
//! 1. Goldens (`golden/bidir19/`) from `fixtures/bidir19_input_ir.json`: a
//!    JSON-input method (`ingest.items`, `Input<Item>`), a binary one
//!    (`ingest.bytes`, `Input<Bytes>`), a streaming one with params
//!    (`ingest.tokens`), and a namespace without input (`bench`).
//! 2. A method without input is generated byte-identical: an IR's every file
//!    is what it was before an input method joined it, but for what the
//!    input half adds — `input.ts`, its export, the transport's hooks
//!    (taken out again, the transport is the template), the base client's
//!    input section and `bytes` in `Cargo.toml`.
//! 3. `tsc --strict` on the generated client with `ts_input/types.test.ts`
//!    beside it, whose `@ts-expect-error` lines are each a real error.
//! 4. `ts_input/live.test.ts` under `node --test` against a real Rust service
//!    with `Input<Item>` and `Input<Bytes>` methods (plexus-bench's
//!    `ingest`, BIDIR-17's branch), through a proxy counting every frame:
//!    pull 10,000 items; push 1 MiB in 640 B chunks as binary frames; never
//!    more than credit in flight; a disconnect mid-push. The service is
//!    `$BIDIR_FIXTURE_SERVER` (default
//!    `/tmp/claude-1000/bidir-fixture/plexus-bench-server`); without it the
//!    run is skipped, unless `SERVICE_CODEGEN_REQUIRE_BIDIR=1`.
//! 5. The generated Rust client compiles (`cargo check`).

use service_codegen::generator::typescript::input as ts_input;
use service_codegen::generator::{GenerationOptions, TransportEnv};
use service_codegen::{generate_rust, generate_typescript, IR};
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::process::Command;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn fixture_json(name: &str) -> serde_json::Value {
    let path = root().join("tests/fixtures").join(format!("{name}.json"));
    serde_json::from_str(&std::fs::read_to_string(path).expect("read fixture")).expect("fixture JSON")
}

fn ir_of(v: &serde_json::Value) -> IR {
    serde_json::from_value(v.clone()).expect("the IR decodes")
}

fn fixture() -> IR {
    ir_of(&fixture_json("bidir19_input_ir"))
}

fn ts(ir: &IR, transport: TransportEnv) -> HashMap<String, String> {
    generate_typescript(ir, &GenerationOptions { transport, ..GenerationOptions::default() })
        .expect("generate typescript")
        .files
}

fn rust(ir: &IR) -> HashMap<String, String> {
    generate_rust(ir).expect("generate rust").files
}

fn golden(name: &str, actual: &str) {
    let path = root().join("tests/golden/bidir19").join(name);
    if std::env::var("UPDATE_GOLDEN").is_ok() {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, actual).expect("write golden");
        return;
    }
    let expected = std::fs::read_to_string(&path).unwrap_or_else(|_| panic!("golden {name} (UPDATE_GOLDEN=1 writes it)"));
    assert_eq!(actual, expected, "{name} diverged from its golden (UPDATE_GOLDEN=1 to accept)");
}

