#[test]
fn ts_goldens() {
    let files = ts(&fixture(), TransportEnv::Browser);
    golden("ts_ingest_client.ts", &files["ingest/client.ts"]);
    golden("ts_bench_client.ts", &files["bench/client.ts"]);
    golden("ts_input.ts", &files["input.ts"]);
    golden("ts_index.ts", &files["index.ts"]);
    golden("ts_transport_browser.ts", &files["transport.ts"]);
}

#[test]
fn rust_goldens() {
    let files = rust(&fixture());
    golden("rust_ingest_mod.rs", &files["src/ingest/mod.rs"]);
    golden("rust_client.rs", &files["src/client.rs"]);
    golden("rust_Cargo.toml", &files["Cargo.toml"]);
}

#[test]
fn ts_signatures() {
    let client = &ts(&fixture(), TransportEnv::Browser)["ingest/client.ts"];
    for line in [
        "  items(input: AsyncIterable<Item> | Iterable<Item>, options?: InputOptions): Promise<IngestEvent>;",
        "  openItems(options?: InputOptions): DuplexCall<Item, Promise<IngestEvent>>;",
        "  bytes(input: AsyncIterable<Uint8Array> | Iterable<Uint8Array>, options?: InputOptions): Promise<IngestEvent>;",
        "  openBytes(options?: InputOptions): DuplexCall<Uint8Array, Promise<IngestEvent>>;",
        "  tokens(run: string, limit: number | undefined, input: AsyncIterable<string> | Iterable<string>, options?: InputOptions): MethodStream<'ingest.tokens', IngestEvent>;",
        "  openTokens(run: string, limit?: number, options?: InputOptions): DuplexCall<string, MethodStream<'ingest.tokens', IngestEvent>>;",
        "    const stream = pullInput<Uint8Array>(this.rpc, 'ingest.bytes', {}, true, input, options);",
        "    const stream = pullInput<Item>(this.rpc, 'ingest.items', {}, false, input, options);",
    ] {
        assert!(client.contains(line), "missing: {line}\n{client}");
    }
}

#[test]
fn rust_signatures() {
    let m = &rust(&fixture())["src/ingest/mod.rs"];
    for line in [
        "pub async fn items(client: &PlexusClient, input: impl Stream<Item = Item> + Send + 'static) -> Result<IngestEvent> {",
        "pub async fn bytes(client: &PlexusClient, input: impl Stream<Item = ::bytes::Bytes> + Send + 'static) -> Result<IngestEvent> {",
        "pub async fn tokens(client: &PlexusClient, run: String, limit: i64, input: impl Stream<Item = String> + Send + 'static) -> Result<Pin<Box<dyn Stream<Item = Result<IngestEvent>> + Send>>> {",
    ] {
        assert!(m.contains(line), "missing: {line}\n{m}");
    }
}

// ─────────────────────────────────────────────────────────────
// 2. A method without input: byte-identical
// ─────────────────────────────────────────────────────────────

/// The fixture without its input halves: the same methods, no `mdInput`.
fn without_input(v: &serde_json::Value) -> serde_json::Value {
    let mut v = v.clone();
    for m in v["irMethods"].as_object_mut().unwrap().values_mut() {
        m.as_object_mut().unwrap().remove("mdInput");
    }
    v
}

/// `fixture` with `feed.push` (`Input<String>`) beside its methods, in a namespace of its own.
fn with_input_method(v: &serde_json::Value) -> serde_json::Value {
    let mut v = v.clone();
    let version = v["irVersion"].as_str().unwrap().to_string();
    let mut m = serde_json::json!({
        "mdName": "push", "mdFullPath": "feed.push", "mdNamespace": "feed",
        "mdDescription": "Lines in.", "mdParams": [],
        "mdReturns": {"tag": "RefPrimitive", "contents": ["integer", "uint64"]},
        "mdBidirType": null, "mdRole": {"kind": "rpc"},
        "mdInput": {"tag": "RefPrimitive", "contents": ["string", null]}
    });
    if version == "3.0" {
        m["mdCardinality"] = "one".into();
    } else {
        m["mdStreaming"] = false.into();
    }
    v["irMethods"]["feed.push"] = m;
    v["irPlugins"]["feed"] = serde_json::json!(["push"]);
    v
}

/// The transport with the input half's hooks taken out again.
fn unhooked(transport: &str) -> String {
    let mut out = transport.to_string();
    for (anchor, replacement) in ts_input::transport_hooks().iter().rev() {
        assert_eq!(out.matches(replacement).count(), 1, "hook applied once: {replacement}");
        out = out.replacen(replacement, anchor, 1);
    }
    out
}

fn index_export() -> String {
    format!("{}\n", ts_input::INDEX_EXPORT.join("\n"))
}

#[test]
fn an_ir_without_input_has_none_of_it() {
    for fx in ["returns38_watch_ir", "synapse_cc_2_injected_ir", "returns15_synapse4_conformance_ir"] {
        let ir = ir_of(&fixture_json(fx));
        assert!(!ir.has_input());
        for transport in [TransportEnv::Ws, TransportEnv::Browser, TransportEnv::None] {
            let files = ts(&ir, transport);
            assert!(!files.contains_key("input.ts"), "{fx}");
            assert!(!files["index.ts"].contains("./input"), "{fx}");
            for (path, content) in &files {
                assert!(!content.contains("InputHalf") && !content.contains("carriesInput") && !content.contains("pullInput"), "{fx}/{path}");
            }
        }
        let files = rust(&ir);
        assert!(!files["src/client.rs"].contains("BIDIR-19"), "{fx}");
        assert!(!files["Cargo.toml"].contains("bytes"), "{fx}");
    }
}

#[test]
fn methods_without_input_are_unchanged_beside_one_with_it() {
    for fx in ["returns38_watch_ir", "synapse_cc_2_injected_ir", "returns15_synapse4_conformance_ir"] {
        let v = fixture_json(fx);
        let (before, after) = (ir_of(&v), ir_of(&with_input_method(&v)));
        for transport in [TransportEnv::Ws, TransportEnv::Browser, TransportEnv::None] {
            let (b, a) = (ts(&before, transport), ts(&after, transport));
            for (path, was) in &b {
                let now = &a[path];
                match path.as_str() {
                    // the version is a hash of the content; the metadata lists the file hashes
                    "package.json" | ".codegen-metadata.json" => {}
                    "transport.ts" => assert_eq!(&unhooked(now), was, "{fx} {transport:?}: transport.ts beyond its hooks"),
                    "index.ts" => {
                        let now = now.replacen(&index_export(), "", 1).replacen("\nexport * as Feed from './feed';", "", 1);
                        assert_eq!(&now, was, "{fx} {transport:?}: index.ts beyond its exports");
                    }
                    _ => assert_eq!(now, was, "{fx} {transport:?}: {path} moved"),
                }
            }
            let new: Vec<&String> = a.keys().filter(|p| !b.contains_key(*p)).collect();
            for p in &new {
                assert!(["input.ts", "feed/client.ts", "feed/index.ts"].contains(&p.as_str()), "{fx}: {p} is new");
            }
        }
        let (b, a) = (rust(&before), rust(&after));
        for (path, was) in &b {
            let now = &a[path];
            match path.as_str() {
                "src/client.rs" => {
                    let at = now.find("\n// === BIDIR-19").expect("the input section");
                    assert_eq!(&now[..at], was.as_str(), "{fx}: client.rs before its input section");
                }
                "src/lib.rs" | "package.json" => {} // the new module's declaration; the content hash
                _ => assert_eq!(now, was, "{fx}: {path} moved"),
            }
        }
    }
}

#[test]
fn the_fixture_without_input_differs_only_in_its_input_methods() {
    let v = fixture_json("bidir19_input_ir");
    let (with, without) = (fixture(), ir_of(&without_input(&v)));
    let (a, b) = (ts(&with, TransportEnv::Browser), ts(&without, TransportEnv::Browser));
    assert_eq!(a["bench/client.ts"], b["bench/client.ts"]);
    assert_eq!(a["ingest/types.ts"], b["ingest/types.ts"]);
    assert_eq!(a["types.ts"], b["types.ts"]);
    assert_eq!(a["rpc.ts"], b["rpc.ts"]);
    assert_eq!(unhooked(&a["transport.ts"]), b["transport.ts"]);
    let (a, b) = (rust(&with), rust(&without));
    assert_eq!(a["src/bench/mod.rs"], b["src/bench/mod.rs"]);
    assert_eq!(a["src/types.rs"], b["src/types.rs"]);
}

// ─────────────────────────────────────────────────────────────
// 3 & 4. tsc --strict, and the run against a real service
// ─────────────────────────────────────────────────────────────

fn harness() -> PathBuf {
    root().join("tests/ts_input")
}

fn run(cmd: &mut Command) -> (bool, String) {
    let out = cmd.output().unwrap_or_else(|e| panic!("{cmd:?}: {e}"));
    let text = format!("{}{}", String::from_utf8_lossy(&out.stdout), String::from_utf8_lossy(&out.stderr));
    (out.status.success(), text)
}

const TSCONFIG: &str = r#"{
  "compilerOptions": {
    "target": "ES2022",
    "module": "commonjs",
    "moduleResolution": "node10",
    "lib": ["ES2022", "DOM"],
    "types": ["node"],
    "strict": true,
    "esModuleInterop": true,
    "skipLibCheck": true,
    "outDir": "out"
  },
  "include": ["*.ts", "ingest/**/*.ts", "bench/**/*.ts", "input-tests/*.ts"]
}"#;

/// The generated package (browser transport: Node 22's WebSocket) with the
/// harness's tests beside it, compiled by `tsc --strict`. `None` without Node.
fn compiled() -> Option<(tempfile::TempDir, PathBuf)> {
    let node_ok = Command::new("node").arg("--version").output().map(|o| o.status.success()).unwrap_or(false);
    if !node_ok {
        assert!(std::env::var("SERVICE_CODEGEN_REQUIRE_TS").is_err(), "SERVICE_CODEGEN_REQUIRE_TS=1 and there is no node");
        eprintln!("node not available; skipping the TypeScript input tests");
        return None;
    }
    let h = harness();
    if !h.join("node_modules/.bin/tsc").exists() {
        let (ok, text) = run(Command::new("npm").args(["ci", "--no-audit", "--no-fund"]).current_dir(&h));
        assert!(ok, "npm ci in {}: {text}", h.display());
    }
    let tmp = tempfile::tempdir().expect("tempdir");
    let pkg = tmp.path().join("pkg");
    for (path, content) in ts(&fixture(), TransportEnv::Browser) {
        let p = pkg.join(&path);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, content).unwrap();
    }
    let tests = pkg.join("input-tests");
    std::fs::create_dir_all(&tests).unwrap();
    for f in ["types.test.ts", "live.test.ts"] {
        std::fs::copy(h.join(f), tests.join(f)).unwrap();
    }
    std::os::unix::fs::symlink(h.join("node_modules"), pkg.join("node_modules")).unwrap();
    std::fs::write(pkg.join("tsconfig.input.json"), TSCONFIG).unwrap();
    let (ok, text) = run(Command::new(h.join("node_modules/.bin/tsc")).args(["-p", "tsconfig.input.json"]).current_dir(&pkg));
    assert!(ok, "tsc --strict rejected the generated package or its tests:\n{text}");
    std::fs::write(pkg.join("out/package.json"), r#"{ "type": "commonjs" }"#).unwrap();
    Some((tmp, pkg))
}

#[test]
fn ts_strict_and_the_type_assertions_are_real() {
    let Some((_tmp, pkg)) = compiled() else { return };
    let types = pkg.join("input-tests/types.test.ts");
    let src = std::fs::read_to_string(&types).unwrap();
    let marked = src.matches("// @ts-expect-error").count();
    assert!(marked >= 7, "{marked} expected errors");
    std::fs::write(&types, src.replace("// @ts-expect-error", "// (unmarked)")).unwrap();
    let (ok, text) = run(Command::new(harness().join("node_modules/.bin/tsc")).args(["-p", "tsconfig.input.json", "--noEmit"]).current_dir(&pkg));
    assert!(!ok, "unmarked, the type tests must fail");
    let errors = text.lines().filter(|l| l.contains("input-tests/types.test.ts") && l.contains("error TS")).count();
    assert_eq!(errors, marked, "one error per marked line:\n{text}");
}

/// The fixture service on a port of its own; killed when dropped.
struct Service(std::process::Child, u16);

impl Drop for Service {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

fn service() -> Option<Service> {
    let bin = std::env::var("BIDIR_FIXTURE_SERVER").unwrap_or_else(|_| "/tmp/claude-1000/bidir-fixture/plexus-bench-server".into());
    if !Path::new(&bin).exists() {
        assert!(std::env::var("SERVICE_CODEGEN_REQUIRE_BIDIR").is_err(), "SERVICE_CODEGEN_REQUIRE_BIDIR=1 and there is no {bin}");
        eprintln!("{bin} not found; skipping the run against a real service");
        return None;
    }
    use std::io::{BufRead, BufReader};
    for attempt in 0..20u16 {
        let port = 47100 + ((std::process::id() as u16).wrapping_mul(37).wrapping_add(attempt * 101)) % 800;
        let mut child = Command::new(&bin)
            .args(["--port", &port.to_string(), "--gate", "none"])
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .spawn()
            .unwrap_or_else(|e| panic!("{bin}: {e}"));
        let mut line = String::new();
        let _ = BufReader::new(child.stdout.take().unwrap()).read_line(&mut line);
        if line.starts_with("listening ") {
            return Some(Service(child, port));
        }
        let _ = child.kill();
        let _ = child.wait();
    }
    panic!("the fixture service would not start");
}

#[test]
fn ts_against_a_real_service() {
    let Some((_tmp, pkg)) = compiled() else { return };
    let Some(svc) = service() else { return };
    let (ok, text) = run(
        Command::new("node")
            .args(["--test", "--test-reporter=spec"])
            .arg(pkg.join("out/input-tests/live.test.js"))
            .env("PLEXUS_BENCH_PORT", svc.1.to_string())
            .current_dir(&pkg),
    );
    println!("{text}");
    assert!(ok, "node --test live.test.js failed:\n{text}");
    assert!(text.contains("pass 5"), "5 live tests:\n{text}");
}

// ─────────────────────────────────────────────────────────────
// 5. The Rust client compiles
// ─────────────────────────────────────────────────────────────

#[test]
fn rust_client_compiles() {
    let tmp = tempfile::tempdir().expect("tempdir");
    for (path, content) in rust(&fixture()) {
        let p = tmp.path().join(&path);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, content).unwrap();
    }
    let (ok, text) = run(Command::new("cargo").arg("check").arg("--manifest-path").arg(tmp.path().join("Cargo.toml")));
    assert!(ok, "the generated Rust client does not compile:\n{text}");
    assert!(!text.contains("src/ingest/mod.rs") && !text.contains("src/client.rs"), "warnings in what BIDIR-19 generates:\n{text}");
}
